 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("B5 Edit required");string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string report=repo+"/Docs/검수/2026-11-08_B5_OperationalDetail";Directory.CreateDirectory(report);if(File.Exists(report+"/before.json"))throw new Exception("Baseline exists");string backup=Path.Combine(Path.GetTempPath(),"AfterSeconds_Operational_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"));Directory.CreateDirectory(backup);File.Copy(Path.GetFullPath(s.path),backup+"/disk_before.unity");bool dirty=s.isDirty;if(dirty){EditorSceneManager.SaveScene(s,backup+"/unsaved_before.unity",true);EditorSceneManager.SaveScene(s);}var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var result=new{scene=s.path,backup,preservedDirty=dirty,rootChildren=root.Cast<Transform>().Select(t=>new{t.name,active=t.gameObject.activeSelf,position=V(t.position)}),hierarchy=root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}),renderers=root.GetComponentsInChildren<Renderer>(true).Select(r=>new{path=P(r.transform),active=r.gameObject.activeInHierarchy,r.enabled,position=V(r.transform.position),rotation=V(r.transform.eulerAngles),center=V(r.bounds.center),size=V(r.bounds.size),mesh=r.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh):"",materials=r.sharedMaterials.Select(m=>m?m.name:null)}),lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=P(l.transform),position=V(l.transform.position),rotation=V(l.transform.eulerAngles),l.enabled,l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()})};File.WriteAllText(report+"/before.json",JsonConvert.SerializeObject